package io.phext.libphext

import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File
import java.security.MessageDigest

/**
 * The shared libphext 0.6 chain conformance fixtures (see FIXTURES.md in
 * the fixture set): all 10 cases from tests/fixtures/chains, generated by
 * libphext-rs 0.6.0. For every case: input size + sha256, chain/member
 * structure, per-member sha256 and phokenize scroll lists (coordinate,
 * byte length, sha256), byte-identical serialize round-trip, and every
 * fetch compared byte-for-byte with its expected file — plus the `found`
 * flag recomputed from phokenize membership, per the manifest definition.
 */
class ChainFixturesTest {

    private val fixturesDir: File = File("tests/fixtures/chains")

    private fun sha256(bytes: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(bytes)
        return digest.joinToString("") { "%02x".format(it) }
    }

    @Test
    fun allChainFixtureCases() {
        assertTrue(fixturesDir.isDirectory, "fixtures dir missing: ${fixturesDir.absolutePath}")
        val casesTsv = File(fixturesDir, "cases.tsv").readText(Charsets.UTF_8)
        val caseNames = casesTsv.lines()
            .filter { it.isNotBlank() }
            .drop(1) // header
            .map { it.split('\t')[0] }
        assertEquals(10, caseNames.size, "expected 10 fixture cases")

        var totalFetches = 0
        for (caseName in caseNames) {
            val caseDir = File(fixturesDir, caseName)
            val manifest = Json.parse(File(caseDir, "manifest.json").readText(Charsets.UTF_8)).asObject()

            val inputBytes = File(caseDir, "input.phext").readBytes()
            assertEquals(manifest["input_bytes"].asLong().toInt(), inputBytes.size, "$caseName input size")
            assertEquals(manifest["input_sha256"].asString(), sha256(inputBytes), "$caseName input sha256")

            val input = inputBytes.toString(Charsets.UTF_8)
            val chains = parseChains(input)

            val chainManifests = manifest["chains"].asArray()
            assertEquals(chainManifests.size, chains.size, "$caseName chain count")
            for ((ci, chainManifest) in chainManifests.withIndex()) {
                val cm = chainManifest.asObject()
                val chain = chains[ci]
                assertEquals(cm["closed"].asBoolean(), chain.closed, "$caseName chain $ci closed")
                val memberManifests = cm["members"].asArray()
                assertEquals(memberManifests.size, chain.members.size, "$caseName chain $ci member count")
                for ((mi, memberManifest) in memberManifests.withIndex()) {
                    val mm = memberManifest.asObject()
                    val member = chain.members[mi]
                    val memberBytes = member.toByteArray(Charsets.UTF_8)
                    assertEquals(mm["bytes"].asLong().toInt(), memberBytes.size, "$caseName chain $ci member $mi bytes")
                    assertEquals(mm["sha256"].asString(), sha256(memberBytes), "$caseName chain $ci member $mi sha256")
                    val scrollManifests = mm["scrolls"].asArray()
                    val phokens = phokenize(member)
                    assertEquals(scrollManifests.size, phokens.size, "$caseName chain $ci member $mi scroll count")
                    for ((si, scrollManifest) in scrollManifests.withIndex()) {
                        val sm = scrollManifest.asObject()
                        val phoken = phokens[si]
                        assertEquals(sm["c"].asString(), phoken.coord.toString(), "$caseName chain $ci member $mi scroll $si coord")
                        val scrollBytes = phoken.scroll.toByteArray(Charsets.UTF_8)
                        assertEquals(sm["b"].asLong().toInt(), scrollBytes.size, "$caseName chain $ci member $mi scroll $si bytes")
                        assertEquals(sm["s"].asString(), sha256(scrollBytes), "$caseName chain $ci member $mi scroll $si sha256")
                    }
                }
            }

            // byte-identical round-trip
            val reserialized = serializeChains(chains).toByteArray(Charsets.UTF_8)
            assertArrayEquals(inputBytes, reserialized, "$caseName round-trip")

            // fetches
            val fetchManifests = manifest["fetches"].asArray()
            for ((fi, fetchManifest) in fetchManifests.withIndex()) {
                val fm = fetchManifest.asObject()
                val chainIndex = fm["chain_index"].asLong().toInt()
                val address = fm["address"].asString()
                val expectedBytes = File(caseDir, fm["expected_file"].asString()).readBytes()
                val result = chains[chainIndex].fetch(address)
                assertArrayEquals(
                    expectedBytes,
                    result.toByteArray(Charsets.UTF_8),
                    "$caseName fetch $fi ($address)",
                )
                assertEquals(fm["expected_bytes"].asLong().toInt(), expectedBytes.size, "$caseName fetch $fi bytes")
                assertEquals(fm["expected_sha256"].asString(), sha256(expectedBytes), "$caseName fetch $fi sha256")

                // found: the coordinate appears in phokenize(member) for the addressed member
                val parsedAddress = parseUniverseAddress(address)
                val found = if (parsedAddress == null) {
                    false
                } else {
                    val (universe, coord) = parsedAddress
                    val member = chains[chainIndex].members.getOrNull((universe - 1).toInt())
                    member != null && phokenize(member).any { it.coord == coord }
                }
                assertEquals(fm["found"].asBoolean(), found, "$caseName fetch $fi ($address) found flag")
                totalFetches += 1
            }
            println("fixture case $caseName: PASS (${fetchManifests.size} fetches)")
        }
        assertEquals(42, totalFetches, "expected 42 fetches across all cases")
    }
}

/** Minimal JSON reader for the fixture manifests (test-only). */
private sealed interface Json {
    data class Obj(val fields: Map<String, Json>) : Json
    data class Arr(val items: List<Json>) : Json
    data class Str(val value: String) : Json
    data class Num(val value: String) : Json
    data class Bool(val value: Boolean) : Json
    object Null : Json

    fun asObject(): Map<String, Json> = (this as Obj).fields
    fun asArray(): List<Json> = (this as Arr).items
    fun asString(): String = (this as Str).value
    fun asLong(): Long = (this as Num).value.toLong()
    fun asBoolean(): Boolean = (this as Bool).value

    companion object {
        fun parse(text: String): Json {
            val parser = Parser(text)
            val value = parser.parseValue()
            parser.skipWhitespace()
            require(parser.atEnd()) { "trailing characters in JSON" }
            return value
        }
    }

    private class Parser(private val text: String) {
        private var pos = 0

        fun atEnd(): Boolean = pos >= text.length

        fun skipWhitespace() {
            while (pos < text.length && text[pos] in " \t\n\r") pos++
        }

        fun parseValue(): Json {
            skipWhitespace()
            return when (text[pos]) {
                '{' -> parseObject()
                '[' -> parseArray()
                '"' -> Str(parseString())
                't' -> { expect("true"); Bool(true) }
                'f' -> { expect("false"); Bool(false) }
                'n' -> { expect("null"); Null }
                else -> parseNumber()
            }
        }

        private fun expect(literal: String) {
            require(text.startsWith(literal, pos)) { "expected $literal at $pos" }
            pos += literal.length
        }

        private fun parseObject(): Json {
            pos++ // {
            val fields = LinkedHashMap<String, Json>()
            skipWhitespace()
            if (text[pos] == '}') { pos++; return Obj(fields) }
            while (true) {
                skipWhitespace()
                val key = parseString()
                skipWhitespace()
                require(text[pos] == ':') { "expected : at $pos" }
                pos++
                fields[key] = parseValue()
                skipWhitespace()
                when (text[pos]) {
                    ',' -> pos++
                    '}' -> { pos++; return Obj(fields) }
                    else -> throw IllegalArgumentException("expected , or } at $pos")
                }
            }
        }

        private fun parseArray(): Json {
            pos++ // [
            val items = ArrayList<Json>()
            skipWhitespace()
            if (text[pos] == ']') { pos++; return Arr(items) }
            while (true) {
                items.add(parseValue())
                skipWhitespace()
                when (text[pos]) {
                    ',' -> pos++
                    ']' -> { pos++; return Arr(items) }
                    else -> throw IllegalArgumentException("expected , or ] at $pos")
                }
            }
        }

        private fun parseString(): String {
            require(text[pos] == '"') { "expected string at $pos" }
            pos++
            val sb = StringBuilder()
            while (true) {
                val c = text[pos++]
                when (c) {
                    '"' -> return sb.toString()
                    '\\' -> {
                        when (val e = text[pos++]) {
                            '"' -> sb.append('"')
                            '\\' -> sb.append('\\')
                            '/' -> sb.append('/')
                            'b' -> sb.append('\b')
                            'f' -> sb.append('\u000C')
                            'n' -> sb.append('\n')
                            'r' -> sb.append('\r')
                            't' -> sb.append('\t')
                            'u' -> {
                                val hex = text.substring(pos, pos + 4)
                                pos += 4
                                sb.append(hex.toInt(16).toChar())
                            }
                            else -> throw IllegalArgumentException("bad escape: $e")
                        }
                    }
                    else -> sb.append(c)
                }
            }
        }

        private fun parseNumber(): Json {
            val start = pos
            while (pos < text.length && text[pos] in "-+0123456789.eE") pos++
            return Num(text.substring(start, pos))
        }
    }
}
